/** Ajoute la banque d'usine de l'instrument (appelé à la fin de chaque description). */
inline void addFactoryBank (grv::engine::ModuleDesc& m)
{
    for (auto& p : m.presets)
    {
        if (p.category.empty()) p.category = banks::classicCategory (m.type, p.name);
        // niveau des sons déjà livrés mis au niveau des banques
        const auto off = banks::classicLevelOffset (m.type, p.name);
        const auto li = m.indexOf ("level");
        if (off == 0.0f || li < 0) continue;
        const auto& lp = m.params[(size_t) li];
        bool found = false;
        for (auto& v : p.values) if (v.first == "level") { v.second = std::clamp (v.second + off, lp.min, lp.max); found = true; }
        if (! found) p.values.push_back ({ "level", std::clamp (lp.def + off, lp.min, lp.max) });
    }
    std::vector<grv::engine::Preset> bank;
    if (m.type == "acid") bank = banks::acidBank();
    if (m.type == "mono") bank = banks::monoBank();
    if (m.type == "poly5") bank = banks::poly5Bank();
    if (m.type == "polyj") bank = banks::polyjBank();
    if (m.type == "hybrid") bank = banks::hybridBank();
    if (m.type == "morph") bank = banks::morphBank();
    if (m.type == "pads") bank = banks::padsBank();
    if (m.type == "fm6") bank = banks::fm6Bank();
    if (m.type == "fm4") bank = banks::fm4Bank();
    if (m.type == "muse") bank = banks::museBank();
    if (m.type == "fmx") bank = banks::fmxBank();
    if (m.type == "hots") bank = banks::hotsBank();
    if (m.type == "lyra") bank = banks::lyraBank();
    if (m.type == "bitm") bank = banks::bitmBank();
    for (auto& p : bank) m.presets.push_back (std::move (p));
    grv::synth::resolveHubPresetDests (m); // destinations de matrice écrites « mx1_dst@réglage »
}

